const body = $('Webhook').first()?.json?.body || {};
const rawInput = body.parameters?.raw_input || body.raw_input || '';
const employees = $input.all().map(item => ({
  id: item.json.employee_code || item.json.id,
  name: item.json.full_name,
  department: item.json.department_name,
  position: item.json.position,
  status: item.json.status
}));

let result = employees;
if (rawInput) {
    const input = rawInput.toLowerCase();

    // Determine if it's a search for a specific name
    let nameSearch = null;
    const nameMatch = input.match(/(?:tên|tên là|là)\s+([a-záàảãạăắằẳẵặâấầẩẫậéèẻẽẹêếềểễệíìỉĩịóòỏõọôốồổỗộơớờởỡợúùủũụưứừửữựýỳỷỹỵđ\s]+)/i);
    if (nameMatch && nameMatch[1]) {
        nameSearch = nameMatch[1].trim(); 
    }

    if (nameSearch) {
        result = employees.filter(emp => nameSearch.includes(emp.name.toLowerCase()) || emp.name.toLowerCase().includes(nameSearch));
        if (result.length === 0) {
            // fallback to parts
            const parts = nameSearch.split(' ');
            result = employees.filter(emp => parts.some(p => p.length > 2 && emp.name.toLowerCase().includes(p)));
        }
    } else {
        // Fallback for department / direct name mention
        if (input.includes('it') || input.includes('công nghệ')) {
            result = employees.filter(emp => emp.department && emp.department.toLowerCase().includes('công nghệ'));
        } else if (input.includes('nhân sự') || input.includes('hr')) {
            result = employees.filter(emp => emp.department && emp.department.toLowerCase().includes('nhân sự'));
        } else {
            // naive fallback
            const matched = employees.filter(emp => {
                const parts = emp.name.toLowerCase().split(' ');
                return parts.some(p => p.length > 2 && input.includes(p));
            });
            if (matched.length > 0 && matched.length < employees.length) {
                result = matched;
            }
        }
    }
}

// Generate Markdown table
let md = "";
if (result.length > 0) {
    if (result.length === 1) {
        md += `**Đã tìm thấy thông tin nhân viên:**\n`;
    } else {
        md += `**Đã lấy danh sách ${result.length} nhân viên:**\n`;
    }

    // Using simple list instead of table for better mobile view, but we can use table or simple bullet points
    result.forEach(emp => {
        md += `- **${emp.name}** (${emp.id})\n`;
        md += `  Phòng ban: ${emp.department || 'N/A'} | Vị trí: ${emp.position || 'N/A'} | Trạng thái: ${emp.status === 'active' ? 'Hoạt động' : 'Nghỉ việc'}\n`;
    });
} else {
    md = "❌ *Không tìm thấy nhân viên nào phù hợp với yêu cầu của bạn.*";
}

return [
  {
    "markdown": md,
    "data": result,
    "message": result.length > 0 ? "Đã lấy danh sách nhân viên từ CSDL thành công!" : "Không tìm thấy nhân viên nào phù hợp!"
  }
];
